use std::path::{Path, PathBuf};

const BASE: &str = "/app/vatlogs";

pub fn gather(a: &str) -> Result<Vec<String>, i32> {
    let base = std::fs::canonicalize(BASE).map_err(|_| 2)?;
    let root = std::fs::canonicalize(a).map_err(|_| 2)?;
    if !root.starts_with(&base) || !root.is_dir() {
        return Err(2);
    }
    let mut paths = Vec::new();
    visit(&root, &base, &mut paths)?;
    if paths.is_empty() {
        return Err(3);
    }
    paths.sort();
    Ok(paths.into_iter().map(|p| p.to_string_lossy().into_owned()).collect())
}

fn visit(dir: &Path, base: &Path, out: &mut Vec<PathBuf>) -> Result<(), i32> {
    let rd = std::fs::read_dir(dir).map_err(|_| 2)?;
    for item in rd {
        let path = item.map_err(|_| 2)?.path();
        let real = std::fs::canonicalize(&path).map_err(|_| 2)?;
        if !real.starts_with(base) {
            return Err(2);
        }
        let meta = std::fs::metadata(&real).map_err(|_| 2)?;
        if meta.is_dir() {
            visit(&real, base, out)?;
        } else if meta.is_file() {
            out.push(real);
        } else {
            return Err(2);
        }
    }
    Ok(())
}
