pub fn clip(a: &[String]) -> Vec<String> {
    a.iter()
        .filter(|s| {
            !(s.starts_with("__asan")
                || s.starts_with("__interceptor")
                || s.starts_with("__hwasan"))
        })
        .map(|s| fold_hex(s))
        .collect()
}

pub fn take(text: &str) -> Result<(String, Vec<String>), i32> {
    if text.trim().is_empty() {
        return Err(3);
    }
    let mut kind: Option<String> = None;
    let mut frames = Vec::new();
    let mut expected = 0usize;
    let mut summary = false;

    for line in text.lines() {
        let t = line.trim();
        if let Some(pos) = t.find("ERROR:") {
            if kind.is_some() || !frames.is_empty() || summary {
                return Err(3);
            }
            let rest = t[pos + "ERROR:".len()..].trim();
            let rest = rest.strip_prefix("AddressSanitizer:").unwrap_or(rest).trim();
            let value = rest.split(" on ").next().unwrap_or("").trim();
            if value.is_empty() {
                return Err(3);
            }
            kind = Some(value.to_string());
        } else if t.starts_with('#') {
            if kind.is_none() || summary {
                return Err(3);
            }
            let mut words = t.split_whitespace();
            let number = words.next().ok_or(3)?;
            let n: usize = number.strip_prefix('#').ok_or(3)?.parse().map_err(|_| 3)?;
            if n != expected {
                return Err(3);
            }
            expected += 1;
            let _address = words.next().ok_or(3)?;
            if words.next() != Some("in") {
                return Err(3);
            }
            let sym = words.next().ok_or(3)?;
            if sym.is_empty() {
                return Err(3);
            }
            frames.push(sym.to_string());
        } else if t.starts_with("SUMMARY:") {
            if kind.is_none() || frames.is_empty() || summary {
                return Err(3);
            }
            summary = true;
        }
    }

    if !summary {
        return Err(3);
    }
    let frames = clip(&frames);
    if frames.is_empty() {
        return Err(3);
    }
    Ok((kind.ok_or(3)?, frames))
}

fn fold_hex(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    while i < bytes.len() {
        if i + 2 <= bytes.len() && bytes[i] == b'0' && bytes[i + 1] == b'x' {
            let mut j = i + 2;
            while j < bytes.len() && bytes[j].is_ascii_hexdigit() {
                j += 1;
            }
            if j > i + 2 {
                out.push_str("<hex>");
                i = j;
                continue;
            }
        }
        let ch = s[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}
