#[path = "../treyfun/clip.rs"]
mod clip;

use std::collections::BTreeMap;

#[derive(Clone)]
pub struct Rec {
    pub issue: i32,
    pub kind: String,
    pub frames: Vec<String>,
    pub body: String,
}

pub fn tally(a: &str) -> Result<Vec<Rec>, i32> {
    let paths = crate::walk::gather(a)?;
    let mut findings: BTreeMap<Vec<String>, Rec> = BTreeMap::new();

    for path in paths {
        let text = std::fs::read_to_string(path).map_err(|_| 3)?;
        let (kind, frames) = clip::take(&text)?;
        let body = frames.join(" | ");
        let candidate = Rec { issue: 0, kind, frames: frames.clone(), body };
        match findings.get_mut(&frames) {
            Some(old) => {
                // Frame identity is authoritative. This tie-break keeps malformed
                // conflicting duplicate metadata deterministic as well.
                if candidate.kind < old.kind {
                    *old = candidate;
                }
            }
            None => {
                findings.insert(frames, candidate);
            }
        }
    }

    let mut recs: Vec<Rec> = findings.into_values().collect();
    for (i, rec) in recs.iter_mut().enumerate() {
        rec.issue = i as i32 + 1;
    }
    write_bound(&recs)?;
    Ok(recs)
}

fn write_bound(recs: &[Rec]) -> Result<(), i32> {
    let tpl = std::fs::read_to_string("/app/tplbay/bound.tpl").map_err(|_| 1)?;
    if !tpl.contains("__ROWS__") {
        return Err(1);
    }
    let mut rows = Vec::new();
    for r in recs {
        rows.push(format!(
            "{{\"issue\":{},\"kind\":{},\"frames\":{},\"body\":{}}}",
            r.issue, jstr(&r.kind), jarr(&r.frames), jstr(&r.body)
        ));
    }
    std::fs::create_dir_all("/app/inkbay").map_err(|_| 1)?;
    std::fs::write("/app/inkbay/bound.json", tpl.replace("__ROWS__", &rows.join(",")))
        .map_err(|_| 1)
}

fn jstr(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '\"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c < ' ' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('\"');
    out
}

fn jarr(v: &[String]) -> String {
    format!("[{}]", v.iter().map(|x| jstr(x)).collect::<Vec<_>>().join(","))
}
